questionvariables.text:
/* pdec: exact decimal display of a value with at most 4 decimal places */
pdec(v) := if integerp(v) then v elseif integerp(10*v) then dispdp(float(v),1) elseif integerp(100*v) then dispdp(float(v),2) elseif integerp(1000*v) then dispdp(float(v),3) else dispdp(float(v),4);
/* Design: second-stage probability depends on the first. [p, q1, q2, context] in hundredths; context 1 vaccination, 2 rain, 3 certified seed, 4 revision. No (a)(i) follow-through node: no offset works on all entries. Source: adapted from SMP AS/A2 Statistics 1, chapter 3, section E, E1. */
L: [[20,15,75,1],[35,70,80,2],[65,30,15,3],[40,80,15,4],[45,70,60,3],[15,20,90,1],[80,60,50,4],[55,65,10,4],[90,25,55,1],[65,25,50,2]];
ix: 1+rand(10);
p: L[ix][1]/100; q1: L[ix][2]/100; q2: L[ix][3]/100; cx: L[ix][4];
/* short labels for the board only (JavaScript strings) */
la: ["Vaccinated","Rain","Certified seed","Revises"][cx];
lna: ["Not vaccinated","No rain","Not certified","Does not revise"][cx];
lb: ["Ill","On time","More than 20 bags","Passes"][cx];
lnb: ["Not ill","Late","20 bags or fewer","Fails"][cx];
ta1: 1-p; ta2: 1-q1; ta3: 1-q2; ta4: p*q1; ta5: p*q1+(1-p)*q2; ta6: 1-ta5;
tl1: min(1/200,ta1/20); tl2: min(1/200,ta2/20); tl3: min(1/200,ta3/20); tl4: min(1/200,ta4/20); tl5: min(1/200,ta5/20); tl6: min(1/200,ta6/20);
/* diagnostics */
d4b: p+q1;
d5b: q1+q2;
d5c: (1-p)*q2;
d6a: (1-p)*(1-q2);
d6b: p*(1-q1);
